#!/bin/bash
# Uninstall script for DisplayLink USB Graphics Software
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling DisplayLink USB Graphics Software..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping DisplayLink USB Graphics Software if running..."
pkill -f "DisplayLink USB Graphics Software" 2>/dev/null || true

# Unload service 73YQY62QM3.com.displaylink.DisplayLinkAPServer
echo "Unloading service 73YQY62QM3.com.displaylink.DisplayLinkAPServer..."
launchctl unload -w /Library/LaunchAgents/73YQY62QM3.com.displaylink.DisplayLinkAPServer.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/73YQY62QM3.com.displaylink.DisplayLinkAPServer.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/73YQY62QM3.com.displaylink.DisplayLinkAPServer.plist 2>/dev/null || true

# Unload service com.displaylink.displaylinkmanager
echo "Unloading service com.displaylink.displaylinkmanager..."
launchctl unload -w /Library/LaunchAgents/com.displaylink.displaylinkmanager.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.displaylink.displaylinkmanager.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.displaylink.displaylinkmanager.plist 2>/dev/null || true

# Unload service com.displaylink.useragent
echo "Unloading service com.displaylink.useragent..."
launchctl unload -w /Library/LaunchAgents/com.displaylink.useragent.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.displaylink.useragent.plist 2>/dev/null || true
