launchctl unload -w /Library/LaunchDaemons/com.displaylink.useragent-prelogin.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.displaylink.useragent-prelogin.plist 2>/dev/null || true

# Unload service com.displaylink.XpcService
echo "Unloading service com.displaylink.XpcService..."
launchctl unload -w /Library/LaunchAgents/com.displaylink.XpcService.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.displaylink.XpcService.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.displaylink.XpcService.plist 2>/dev/null || true

# Kill application with bundle ID DisplayLinkUserAgent if running
echo "Stopping application with bundle ID DisplayLinkUserAgent if running..."
killall -9 "DisplayLinkUserAgent" 2>/dev/null || true

# Remove $HOME/Library/Application Scripts/73YQY62QM3.com.displaylink.DisplayLinkShared
echo "Removing $HOME/Library/Application Scripts/73YQY62QM3.com.displaylink.DisplayLinkShared..."
if [ -d "$HOME/Library/Application Scripts/73YQY62QM3.com.displaylink.DisplayLinkShared" ]; then
    rm -rf "$HOME/Library/Application Scripts/73YQY62QM3.com.displaylink.DisplayLinkShared" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Scripts/73YQY62QM3.com.displaylink.DisplayLinkShared" ]; then
    rm -f "$HOME/Library/Application Scripts/73YQY62QM3.com.displaylink.DisplayLinkShared" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Scripts/com.displaylink.DisplayLinkUserAgent
echo "Removing $HOME/Library/Application Scripts/com.displaylink.DisplayLinkUserAgent..."
if [ -d "$HOME/Library/Application Scripts/com.displaylink.DisplayLinkUserAgent" ]; then
    rm -rf "$HOME/Library/Application Scripts/com.displaylink.DisplayLinkUserAgent" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Scripts/com.displaylink.DisplayLinkUserAgent" ]; then
    rm -f "$HOME/Library/Application Scripts/com.displaylink.DisplayLinkUserAgent" 2>/dev/null || true
fi

# Remove $HOME/Library/Containers/com.displaylink.DisplayLinkUserAgent
echo "Removing $HOME/Library/Containers/com.displaylink.DisplayLinkUserAgent..."
if [ -d "$HOME/Library/Containers/com.displaylink.DisplayLinkUserAgent" ]; then
    rm -rf "$HOME/Library/Containers/com.displaylink.DisplayLinkUserAgent" 2>/dev/null || true
elif [ -f "$HOME/Library/Containers/com.displaylink.DisplayLinkUserAgent" ]; then
    rm -f "$HOME/Library/Containers/com.displaylink.DisplayLinkUserAgent" 2>/dev/null || true
fi

# Remove $HOME/Library/Group Containers/73YQY62QM3.com.displaylink.DisplayLinkShared
echo "Removing $HOME/Library/Group Containers/73YQY62QM3.com.displaylink.DisplayLinkShared..."
if [ -d "$HOME/Library/Group Containers/73YQY62QM3.com.displaylink.DisplayLinkShared" ]; then
    rm -rf "$HOME/Library/Group Containers/73YQY62QM3.com.displaylink.DisplayLinkShared" 2>/dev/null || true
elif [ -f "$HOME/Library/Group Containers/73YQY62QM3.com.displaylink.DisplayLinkShared" ]; then
    rm -f "$HOME/Library/Group Containers/73YQY62QM3.com.displaylink.DisplayLinkShared" 2>/dev/null || true
